<?php require 'config.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM categories WHERE id=?');$s->execute([$id]);$category=$s->fetch();if(!$category){flash('Category not found.','error');go('/MediHome/medicines.php');}$s=$pdo->prepare('SELECT m.*,c.name category_name FROM medicines m JOIN categories c ON c.id=m.category_id WHERE m.category_id=? ORDER BY m.is_featured DESC,m.name');$s->execute([$id]);$products=$s->fetchAll();$title=$category['name'].' | MediHome';require 'includes/header.php';?><div class="category-hero"><span class="caticon"><?=e($category['icon'])?></span><div><span class="eyebrow">Explore category</span><h1><?=e($category['name'])?></h1><p>Browse items in this category and open a product to see more information.</p></div></div><div class="sectionhead"><div><h2><?=count($products)?> product(s)</h2><p>Explore available products in this category.</p></div><a href="/MediHome/medicines.php">← All products</a></div><?php if($products):?><div class="products"><?php foreach($products as $p) require 'includes/card.php';?></div><?php else:?><div class="empty"><h2>No products in this category yet</h2><a class="btn" href="/MediHome/medicines.php">Browse all products</a></div><?php endif;?><?php require 'includes/footer.php';?>